/** ISO time the app was built, injected by Vite. */
declare const __BUILD_TIME__: string;

/** Android versionCode of this build ("0" for local builds), injected by Vite from APP_VERSION_CODE. */
declare const __APP_CODE__: string;
/** Human version name, like "1.0.12" ("dev" for local builds). */
declare const __APP_VERSION__: string;
